import { describe, expect, it } from "vitest";
import household from "../test/fixtures/lifecycle/default-household.json";
import metadata from "../test/fixtures/lifecycle/published-measures.json";
import { buildMeasureCatalogue } from "./measureCatalogue";
import { lifecycleSelection, lifecycleTotals } from "./lifecycleSelection";

// Registry metadata is generated by the pipeline test, never duplicated as a
// frontend mapping. This fixture keeps the existing household API contract.
const catalogue = buildMeasureCatalogue({ budgetary: metadata.map((measure) => ({
  reform_id: measure.id,
  reform_name: measure.name,
  reform_description: measure.description,
  reform_personal: JSON.stringify(measure.personal),
  value: "0",
})) });

describe("published mappings for the existing household API", () => {
  it("resolves all nine measures to the seven existing response series", () => {
    expect(catalogue.measures).toHaveLength(9);
    const ids = catalogue.measures.map((measure) => measure.id);
    const selected = lifecycleSelection(ids, catalogue.measures, household.data);
    expect(selected.unmodelled).toEqual([]);
    expect(selected.partialCombined).toBe(false);
    expect(selected.reforms).toHaveLength(7);
    const keys = [...new Set(metadata.map((measure) => measure.personal.key))];
    expect(selected.reforms.map((reform) => reform.key).sort()).toEqual(keys.sort());
    const expected = household.data.reduce((total, row) =>
      total + keys.reduce((sum, key) => sum + row[key], 0), 0);
    expect(lifecycleTotals(household.data, selected.reforms)).toEqual({
      netTotal: expected,
      avgPerYear: expected / household.data.length,
    });
  });

  it("requires the complete published shared group without inventing a partial total", () => {
    const member = catalogue.measures.find((measure) => measure.personal.policies?.length > 1);
    const selected = lifecycleSelection([member.id], catalogue.measures, household.data);
    expect(selected.partialCombined).toBe(true);
    expect(selected.reforms).toEqual([]);
    expect(selected.unmodelled).toEqual([member.label]);
    expect(lifecycleTotals(household.data, selected.reforms).netTotal).toBeNull();
  });
});
